pub fn is_prime(n: i8) -> bool {
    // By definition, primes are integers >= 2.
    if n < 2 {
        return false;
    }

    // Check for any divisor k with 2 <= k < n.
    // If one exists, n is not prime.
    let mut k: i8 = 2;
    while k < n {
        if n % k == 0 {
            return false;
        }
        k += 1;
    }

    // No divisor found in [2, n), so n is prime by the given definition.
    true
}